/// 10-minute wait for the external watchdog.
void main() {
  group('StuckToolConfig thresholds', () {
    test(
      'threshold is the greater of (factor × declared timeout) and floor',
      () {
        const config = StuckToolConfig(
          floor: Duration(seconds: 300),
