+
+/// One supervised execution attempt's outcome.
+final class _SupervisedAttempt {
+  _SupervisedAttempt.completed(this.result, {required this.afterStuck})
+    : error = null,
+      hung = false,
+      elapsed = Duration.zero,
+      outputBytes = 0,
+      partialText = '';
