            streamed = true;
            final empty = AssistantMessage(
              content: const [],
              api: 'a',
              provider: 'p',
              model: 'm',
              usage: Usage.zero,
              stopReason: StopReason.stop,
              timestamp: DateTime.utc(2026),
            );
            final partial = AssistantMessage(
              content: calls,
              api: 'a',
              provider: 'p',
              model: 'm',
              usage: Usage.zero,
              stopReason: StopReason.toolUse,
              timestamp: DateTime.utc(2026),
            );
            stream.push(StartEvent(partial: empty));
            stream.push(ToolCallStartEvent(contentIndex: 0, partial: empty));
            stream.push(
              ToolCallEndEvent(
                contentIndex: 0,
                toolCall: calls[0],
                partial: partial,
              ),
            );
            stream.push(DoneEvent(reason: StopReason.toolUse, message: partial));
          } else {
            final msg = AssistantMessage(
              content: const [TextContent(text: 'done')],
              api: 'a',
              provider: 'p',
              model: 'm',
              usage: Usage.zero,
              stopReason: StopReason.stop,
              timestamp: DateTime.utc(2026),
            );
            stream.push(StartEvent(partial: msg));
            stream.push(DoneEvent(reason: StopReason.stop, message: msg));
          }
          stream.end();
          return stream;
